/* 把一份配置压成「够认出这是哪个版本」的一行摘要。
   为什么放在目录里：dims/labels 是目录的一部分，只有它知道哪些维度是 primary
   （版本身份：功能 / 协议 / 按键数 / 颜色），哪些是规格细节（电压 / 负载 / App / 底盒）。
   Drawer 与 Quote List **共用这一份实现** —— 以前两边各写一份 configText/primarySummary，
   同一种数据必然漂成两种排版。
   精简不等于藏起来：被隐去的用 hidden 计数明说，完整串由调用方挂 title，编辑态里始终是全的。
   返回 null 表示没有可展示的配置。 */
window.Z02_CONFIG_SUMMARY = function (rec, attrs, max) {
  if (!rec || !attrs) return null;
  var info = (window.Z02_CATALOG.dims || {})[rec.categoryPage] || {};
  var order = info.dimensions || [];
  var labels = info.labels || {};
  var parts = [];
  var seen = {};
  var push = function (key) {
    if (seen[key] || !attrs[key] || !attrs[key].length) return;
    seen[key] = true;
    parts.push(
      attrs[key]
        .map(function (v) {
          return (labels[key] && labels[key][v]) || v;
        })
        .join(' / ')
    );
  };
  order.forEach(function (d) { if (d.primary) push(d.key); }); /* 版本身份优先 */
  order.forEach(function (d) { push(d.key); });               /* 未标 primary 的细节跟在后面 */
  Object.keys(attrs).forEach(push);                           /* 数据里没列的维度也不能丢 */
  if (!parts.length) return null;
  var limit = max > 0 ? max : 5;
  return {
    text: parts.slice(0, limit).join(' \u00b7 '),
    hidden: Math.max(0, parts.length - limit),
    full: parts.join(' \u00b7 ')
  };
};
